static async Task ReadExactlyCompatAsync(
    Stream stream, Memory<byte> buffer, CancellationToken ct)
{
    var offset = 0;
    while (offset < buffer.Length)
    {
        var n = await stream.ReadAsync(buffer[offset..], ct);
        if (n == 0)
            throw new EndOfStreamException("Message chưa hoàn chỉnh");
        offset += n;
    }
}
