// Program.cs
builder.Services.AddHttpClient("PartnerApi", c =>
{
    c.BaseAddress = new Uri("https://api.example.com/");
    c.Timeout = TimeSpan.FromSeconds(10);
});

// Trong service nhận IHttpClientFactory qua constructor
public async Task<string> GetDataAsync(CancellationToken ct)
{
    using var client = _factory.CreateClient("PartnerApi");
    using var response = await client.GetAsync("data", ct);
    response.EnsureSuccessStatusCode();
    return await response.Content.ReadAsStringAsync(ct);
}
